def countDominantOnes(s):
    n = len(s)
    Z = [i for i, c in enumerate(s) if c == '0']
    m = len(Z)
    total = 0
    zi = 0  # zeros strictly before l
    for l in range(n):
        k = 0
        while True:
            need = l + k * k + k - 1
            if need >= n:
                break
            if k == 0:
                a = l
            else:
                if zi + k - 1 >= m:
                    break
                a = Z[zi + k - 1]
            b = Z[zi + k] - 1 if zi + k < m else n - 1
            lo = need if need > a else a
            if lo <= b:
                total += b - lo + 1
            k += 1
        if s[l] == '0':
            zi += 1
    return total
